using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public static class ConRoiModelLocations {
 const string O="Docs/Reviews/model_locations";static JArray meshes,mats,objects,skipped;static Dictionary<UnityEngine.Object,int> mid,matid;static BinaryWriter bin;
 static JArray V(Vector3 p)=>new JArray(p.x,p.y,p.z);
 static string Abs(string p)=>string.IsNullOrEmpty(p)?p:Path.GetFullPath(p);
 static string Hier(Transform t){return t.parent?Hier(t.parent)+"/"+t.name:t.name;}
 static bool Active(Transform t,Transform root){while(t&&t!=root){if(!t.gameObject.activeSelf)return false;t=t.parent;}return true;}
 static int Material(Material m){if(!m)return -1;if(matid.TryGetValue(m,out int id))return id;id=mats.Count;matid.Add(m,id);var tex=m.HasProperty("_BaseMap")?m.GetTexture("_BaseMap"):m.HasProperty("_MainTex")?m.GetTexture("_MainTex"):null;var color=m.HasProperty("_BaseColor")?m.GetColor("_BaseColor"):m.HasProperty("_Color")?m.color:Color.gray;var scale=m.HasProperty("_BaseMap")?m.GetTextureScale("_BaseMap"):m.HasProperty("_MainTex")?m.GetTextureScale("_MainTex"):Vector2.one;var off=m.HasProperty("_BaseMap")?m.GetTextureOffset("_BaseMap"):m.HasProperty("_MainTex")?m.GetTextureOffset("_MainTex"):Vector2.zero;
 mats.Add(new JObject{["id"]=id,["name"]=m.name,["asset"]=Abs(AssetDatabase.GetAssetPath(m)),["shader"]=m.shader?m.shader.name:null,["color"]=new JArray(color.r,color.g,color.b,color.a),["texture"]=tex?Abs(AssetDatabase.GetAssetPath(tex)):null,["uv_scale"]=new JArray(scale.x,scale.y),["uv_offset"]=new JArray(off.x,off.y),["smoothness"]=m.HasProperty("_Smoothness")?m.GetFloat("_Smoothness"):0});return id;}
 static int MeshData(Mesh m,bool baked){if(!baked&&mid.TryGetValue(m,out int id))return id;id=meshes.Count;if(!baked)mid.Add(m,id);var v=m.vertices;var n=m.normals;var uv=m.uv;long offset=bin.BaseStream.Position;bin.Write(v.Length);foreach(var p in v){bin.Write(p.x);bin.Write(p.y);bin.Write(p.z);}bin.Write(n.Length);foreach(var p in n){bin.Write(p.x);bin.Write(p.y);bin.Write(p.z);}bin.Write(uv.Length);foreach(var p in uv){bin.Write(p.x);bin.Write(p.y);}bin.Write(m.subMeshCount);int tris=0;for(int j=0;j<m.subMeshCount;j++){var t=m.GetTriangles(j);bin.Write(t.Length);foreach(int k in t)bin.Write(k);tris+=t.Length/3;}string guid="";long local=0;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m,out guid,out local);meshes.Add(new JObject{["id"]=id,["name"]=m.name,["asset"]=Abs(AssetDatabase.GetAssetPath(m)),["guid"]=guid,["local_file_id"]=local,["offset"]=offset,["vertices"]=v.Length,["triangles"]=tris,["baked_static_pose"]=baked});return id;}
 public static void Run(){Directory.CreateDirectory(O);EditorSceneManager.OpenScene("Assets/Scenes/JourneyRepair_v48_r28.unity");var s=UnityEngine.Object.FindAnyObjectByType<DieuPhoiHanhTrinh>();meshes=new JArray();mats=new JArray();objects=new JArray();skipped=new JArray();mid=new Dictionary<UnityEngine.Object,int>();matid=new Dictionary<UnityEngine.Object,int>();
 var regions=new List<(string,Transform)>{("01_Lake_Bridge_Bao",s.lake.transform),("02_Market",s.market.transform),("03_School_R28",s.schoolChapter.environment.transform),("04_Slope_R27",s.slopeChapter.environment.transform)};
 var shared=s.GetComponent<CanhQuanChoV48>();foreach(var g in shared.scenery)if(g&&!regions.Any(p=>g.transform.IsChildOf(p.Item2)))regions.Add(("00_Shared_Lake_Market",g.transform));
 foreach(var g in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())if(g.activeSelf&&(g.name=="StoryProps"||g.name=="RouteSurfaces"||g.name=="R22_Market_Front_Detail"))regions.Add(("05_Other_Visible",g.transform));
 using(bin=new BinaryWriter(File.Open(O+"/meshes.bin",FileMode.Create))){foreach(var (region,root) in regions){foreach(var r in root.GetComponentsInChildren<Renderer>(true)){
  if(!Active(r.transform,root)||!r.enabled){skipped.Add(new JObject{["region"]=region,["hierarchy"]=Hier(r.transform),["reason"]=!r.enabled?"renderer disabled":"inactive child under chapter root"});continue;}
  Mesh m=null;bool baked=false;var sk=r as SkinnedMeshRenderer;if(sk){m=new Mesh();sk.BakeMesh(m);baked=true;}else {var f=r.GetComponent<MeshFilter>();if(f)m=f.sharedMesh;}
  var tm=r.GetComponent<TextMesh>();if(!m){skipped.Add(new JObject{["region"]=region,["hierarchy"]=Hier(r.transform),["reason"]=tm?"TextMesh retained as annotation":"renderer has no MeshFilter",["text"]=tm?tm.text:null});continue;}
  try{int id=MeshData(m,baked);var matrix=r.localToWorldMatrix;var rows=new JArray();for(int a=0;a<4;a++){var row=new JArray();for(int b=0;b<4;b++)row.Add(matrix[a,b]);rows.Add(row);}var prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject);objects.Add(new JObject{["region"]=region=="05_Other_Visible"&&r.bounds.center.x>0?"00_Shared_Lake_Market":region,["name"]=r.name,["hierarchy"]=Hier(r.transform),["mesh"]=id,["matrix_unity_world"]=rows,["local_position"]=V(r.transform.localPosition),["local_scale"]=V(r.transform.localScale),["prefab"]=Abs(prefab),["materials"]=new JArray(r.sharedMaterials.Select(Material)),["bounds_min"]=V(r.bounds.min),["bounds_max"]=V(r.bounds.max)});}catch(Exception e){throw new Exception(Hier(r.transform)+": "+e.Message,e);}finally{if(baked)UnityEngine.Object.DestroyImmediate(m);}
 }}}
 var extra=new JArray(UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include).Where(r=>!regions.Any(p=>r.transform.IsChildOf(p.Item2))).Select(r=>new JObject{["hierarchy"]=Hier(r.transform),["active"]=r.gameObject.activeInHierarchy,["enabled"]=r.enabled}));
 var deps=AssetDatabase.GetDependencies("Assets/Scenes/JourneyRepair_v48_r28.unity",true);File.WriteAllText(O+"/unity-inventory.json",new JObject{["scene"]=Abs("Assets/Scenes/JourneyRepair_v48_r28.unity"),["root_activation"]="Chapter root inactive is ignored; only activeSelf beneath it and renderer.enabled count. Serialized rest pose, no Play Mode, no saves.",["outside_regions"]=extra,["shared_scenery_roots"]=new JArray(shared.scenery.Select(g=>Hier(g.transform))),["objects"]=objects,["meshes"]=meshes,["materials"]=mats,["excluded"]=skipped,["all_scene_dependencies_including_disabled"]=new JArray(deps.Select(Abs))}.ToString());Debug.Log("MODEL_LOCATIONS "+objects.Count+" objects "+meshes.Count+" meshes");
 }
}
